// Mở rộng kho đề và cho phép xem lại các câu sai trong lịch sử.
function card(e){
  const label=e.subject==='math'?'∑ &nbsp; TOÁN 10':e.subject==='chemistry'?'⚗ &nbsp; HÓA HỌC 10':'⚛ &nbsp; VẬT LÝ 10';
  return `<article class="exam-card"><div class="card-top"><span class="subject-pill">${label}</span><span class="card-code">${e.id}</span></div><h3>${e.title}</h3><p>${e.description}</p><div class="meta"><span>◷ &nbsp; ${e.minutes} phút</span><span>☷ &nbsp; ${e.questions.length} nhiều lựa chọn</span><span>✓ &nbsp; ${e.tf.length} đúng/sai</span><span>✎ &nbsp; ${e.short.length} trả lời ngắn</span></div>${sourceLine(e)}<div class="card-bottom"><span>Giữa học kì I</span><button class="primary" data-start="${e.id}">Bắt đầu làm bài →</button></div></article>`;
}
function tiles(){
  const counts={0:'math',1:'physics',5:'chemistry'};
  return `<div class="subject-grid">${subjects.map((s,i)=>`<button class="subject-tile" data-subjectto="${i}"><span class="tile-icon" style="background:${s[2]};color:${s[3]}">${s[1]}</span><b>${s[0]}</b><small>${counts[i]?exams.filter(e=>e.subject===counts[i]).length+' đề thi':'Sắp cập nhật đề thi'}</small></button>`).join('')}</div>`;
}
function home(){
  const groups=[['math',0,'Toán 10 · Giữa kì I','Mệnh đề, tập hợp, bất phương trình và hệ thức lượng'],['physics',1,'Vật lý 10 · Giữa kì I','Ưu tiên nguồn Quảng Trị và miền Trung'],['chemistry',5,'Hóa học 10 · Giữa kì I','Cấu tạo nguyên tử và bảng tuần hoàn']];
  app.innerHTML=`<div class="content"><section class="hero"><div class="hero-copy"><span class="eyebrow">✦ &nbsp; KHÔNG GIAN HỌC TẬP CỦA BẠN</span><h1>Học tập hôm nay,<br>tự tin ngày mai.</h1><p>Luyện đề Toán, Vật lý và Hóa học lớp 10 với đồng hồ thi, ba dạng câu hỏi và phần xem lại bài đã nộp.</p></div><div class="hero-art"><div class="orbit"></div><div class="planet one">📚</div><div class="planet two">∑</div><div class="planet three">✦</div></div></section><section class="stats"><div class="stat"><span class="stat-icon purple">▦</span><div><b>07</b><small>Môn học</small></div></div><div class="stat"><span class="stat-icon orange">☷</span><div><b>${String(exams.length).padStart(2,'0')}</b><small>Đề thi sẵn sàng</small></div></div><div class="stat"><span class="stat-icon green">◷</span><div><b>${String(saved().length).padStart(2,'0')}</b><small>Lượt thi đã hoàn thành</small></div></div></section>${groups.map(([subject,index,title,desc])=>{const list=exams.filter(e=>e.subject===subject);return `<section class="lower-section"><div class="section-head"><div><h2>${title}</h2><p>${list.length} bài luyện · ${desc}</p></div><button class="text-link" data-subjectto="${index}">Xem tất cả →</button></div><div class="cards">${list.slice(0,4).map(card).join('')}</div></section>`}).join('')}<section class="lower-section"><div class="section-head"><div><h2>Khám phá môn học</h2><p>7 môn trong tổ hợp học tập của bạn</p></div></div>${tiles()}</section></div>`;
  setNav('home');
}
function catalog(index){
  const mapping={0:'math',1:'physics',5:'chemistry'},list=index===undefined?exams:exams.filter(e=>e.subject===mapping[index]);
  const name=index===undefined?'Kho đề thi':subjects[index][0];
  app.innerHTML=`<div class="content"><div class="page-heading"><h1>${name}</h1><p>${list.length?`${list.length} bài luyện giữa kì I lớp 10 · Nhiều lựa chọn, đúng/sai và trả lời ngắn · Không có tự luận.`:'Môn học này đang được cập nhật đề thi.'}</p></div>${index===undefined?`<div class="filter-row"><button class="filter active" data-viewto="subjects">Tất cả</button>${[[0,'Toán'],[1,'Vật lý'],[5,'Hóa học']].map(([i,n])=>`<button class="filter" data-subjectto="${i}">${n} (${exams.filter(e=>e.subject===mapping[i]).length})</button>`).join('')}</div>`:''}${list.length?`<div class="cards">${list.map(card).join('')}</div>`:`<div class="notice"><b>Đề thi đang được cập nhật</b>Môn ${name} chưa có bộ đề.<br><br><button class="primary" data-viewto="subjects">Xem kho đề →</button></div>`}${index===undefined?`<section class="lower-section"><div class="section-head"><h2>Danh sách môn học</h2></div>${tiles()}</section>`:''}</div>`;
  setNav(index===undefined?'subjects':'subject-'+index);
}
function history(){
  const items=saved();
  app.innerHTML=`<div class="content"><div class="page-heading"><h1>Lịch sử làm bài</h1><p>Kết quả và đáp án đã chọn được lưu trên trình duyệt của thiết bị này. Bấm “Xem câu sai” để ôn lại bài đã làm.</p></div>${items.length?`<div class="history-list">${items.map((x,i)=>`<div class="history-item"><div><strong>${esc(x.title)}</strong><small>${formatDate(x.date)} · ${x.reason==='time'?'Hết giờ':'Đã nộp bài'} · ${Math.max(0,x.total-x.correct)} ý sai hoặc bỏ trống</small></div><div class="history-actions"><span class="history-score">${x.correct}/${x.total}</span><button class="secondary" data-review="${i}">Xem câu sai →</button></div></div>`).join('')}</div>`:`<div class="notice"><b>Chưa có bài thi nào</b>Hãy thử một bộ đề để bắt đầu theo dõi kết quả.<br><br><button class="primary" data-viewto="subjects">Khám phá đề thi →</button></div>`}</div>`;
  setNav('history');
}
function reviewPast(index){
  const r=saved()[index];if(!r)return history();
  const e=typeof historicalExamForResult==='function'?historicalExamForResult(r):exams.find(x=>x.id===r.id);
  if(!e){app.innerHTML=`<div class="content"><div class="notice"><b>Không tìm thấy bộ đề gốc</b>Điểm của bài vẫn được lưu: ${r.correct}/${r.total}.<br><br><button class="primary" data-viewto="history">Về lịch sử</button></div></div>`;return setNav('history')}
  const a=r.answers||{},legacy=r.total===e.questions.length,wrong=[];
  e.questions.forEach((q,i)=>{const chosen=a['m'+i]??a[i];if(chosen===undefined||chosen!==q[2])wrong.push(`<div class="review-item"><b>Phần I · Câu ${i+1}. ${q[0]}</b><span class="incorrect">Bạn chọn: ${chosen===undefined?'Chưa trả lời':`${'ABCD'[chosen]}. ${cleanOptionText(q[1][chosen])}`}</span><br><span class="correct">Đáp án đúng: ${'ABCD'[q[2]]}. ${cleanOptionText(q[1][q[2]])}</span><br><span class="review-explain">${q[3]||''}</span></div>`)});
  if(!legacy){const isTrue=v=>(v===true||v==='true'||v==='Đúng'||v==='đúng');const isMatch=(u,exp)=>u!==undefined&&u!==null&&Boolean(u)===isTrue(exp);e.tf.forEach((q,i)=>q.items.forEach((item,j)=>{const chosen=a['t'+i+'-'+j];const ok=isMatch(chosen,item[1]);const expTrue=isTrue(item[1]);if(!ok)wrong.push(`<div class="review-item"><b>Phần II · Câu ${i+1}${'abcd'[j]}. ${cleanItemText(item[0])}</b><span class="incorrect">Bạn chọn: ${chosen===undefined?'Chưa trả lời':chosen?'Đúng':'Sai'}</span><br><span class="correct">Đáp án đúng: ${expTrue?'Đúng':'Sai'}</span>${item[2]?`<br><span class="review-explain">${item[2]}</span>`:''}</div>`)}));e.short.forEach((q,i)=>{const chosen=a['s'+i];if(!shortCorrect(chosen,q.answer))wrong.push(`<div class="review-item"><b>Phần III · Câu ${i+1}. ${q.text||q.question}</b><span class="incorrect">Bạn nhập: ${esc(chosen??'Chưa trả lời')}</span><br><span class="correct">Đáp án đúng: ${esc(q.answer)}${q.unit?' '+esc(q.unit):''}</span><br><span class="review-explain">${q.explain||q.explanation||''}</span></div>`)})}
  app.innerHTML=`<div class="content"><div class="result-panel"><div class="result-icon">📘</div><h1>Xem lại bài đã làm</h1><p>${esc(r.title)} · ${formatDate(r.date)}</p><div class="score">${r.correct}/${r.total}</div><p>${wrong.length} ý sai hoặc bỏ trống${legacy?' · Bài cũ chỉ có phần nhiều lựa chọn':''}</p>${sourceLine(e)}<div class="review-actions"><button class="secondary" data-viewto="history">← Lịch sử làm bài</button><button class="primary" data-start="${e.id}">Làm lại đề này</button></div><div class="review"><div class="section-head"><h2>Các câu cần ôn lại</h2></div>${wrong.length?wrong.join(''):'<div class="notice"><b>Không có câu sai</b>Bạn đã trả lời đúng toàn bộ bài này.</div>'}</div></div></div>`;
  setNav('result');window.scrollTo(0,0);
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-review]');if(button)reviewPast(Number(button.dataset.review))});
home();
